'use strict';
const C=window.COMMUNITY,R=window.COMMUNITY_V2,Art=window.CommunityArt,$=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SOURCES={...C.sources,...R.sources},cats=Object.fromEntries(C.categories.map(c=>[c[0],c]));
const readLocal=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},writeLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const ARTICLES=[...C.articles.map(a=>({id:a[0],cat:a[1],title:a[2],audience:a[3],hook:a[4],actions:a[5],avoid:a[6],warning:a[7],sources:a[9],...R.details[a[0]]})),...R.extra];
const byId=Object.fromEntries(ARTICLES.map(a=>[a.id,a]));
let saved=readLocal('nur-community-saved',[]);if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>byId[id]);
let fontLevel=Number(readLocal('nur-community-font-v2',0));if(![0,1,2].includes(fontLevel))fontLevel=0;
let pathFilter='all',category='all',query='',visible=12,installEvent=null,activeTopic=null;
const safeStorage={getItem:k=>{try{return localStorage.getItem(k)}catch{return null}},setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
const scenarioById=Object.fromEntries(window.CommunityScenarios.items.map(s=>[s.id,s]));
const simulationRecords=new window.CommunitySimulation.Records(safeStorage);
let simulationRun=null;
const surveyStore=new window.CommunitySurvey(safeStorage);
const measurement=new window.CommunityMeasure(safeStorage),featured=['pcos','child-tonsillitis','migraine','sinusitis','eczema','diabetes','blood-pressure','kidney-disease','gout','women-health','mental-anxiety','addiction-help','diabetes-sick-days','diabetes-food-portions','diabetes-high-correction','h-pylori','school-day','home-kit','produce-pesticides','health-waste','conserve-water'];
const listHTML=items=>'<ul>'+items.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul>';
const normalize=s=>String(s).toLowerCase().normalize('NFKD').replace(/[\u064b-\u065f\u0670]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/ـ/g,'');
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function applyFont(){document.documentElement.setAttribute('data-font',String(fontLevel));$('#fontSize').textContent=['نص أكبر +','نص أكبر ++','الحجم العادي'][fontLevel];$('#fontSize').setAttribute('aria-label','تغيير حجم النص الحالي '+['عادي','كبير','أكبر'][fontLevel]);}
function star(id){return `<button class="bookmark" data-save="${id}" aria-label="${saved.includes(id)?'إزالة من':'إضافة إلى'} المحفوظات" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'★':'☆'}</button>`}
function card(a){return `<article class="story-card"><a href="#topic=${a.id}" class="card-art">${Art.render(a.art,a.title)}</a><div class="card-copy"><div class="card-top"><span class="label">${esc(cats[a.cat][1])}</span>${star(a.id)}</div><a href="#topic=${a.id}"><h3>${esc(a.title)}</h3><p>${esc(a.hook)}</p><span class="read">افتح الموضوع ←</span></a></div></article>`}
function nursingRoleIntro(){const role=R.nursingRole;return `<section class="nursing-role-intro panel" aria-labelledby="nursingRoleTitle"><span class="label">لماذا يقدم طلاب التمريض هذه التوعية؟</span><h2 id="nursingRoleTitle">${esc(role.title)}</h2><p>${esc(role.intro)}</p><details><summary>عن المبادرة ومراجعها المهنية</summary><p>${esc(role.scope)}</p>${referenceDetails(role.sources.map(k=>SOURCES[k]),'المراجع المهنية لدور التمريض')}</details><div class="choice-row"><button class="button" id="readNursingRole">استمع لدور التمريض</button><a class="button" href="#students">المبادرة والإشراف</a></div></section>`;}
function workersPage(){return `<section class="page-head"><span class="label">صحتك أثناء الدوام</span><h1>صحة العاملين: اختر ظروف عملك</h1><p>للواقف طويلًا، وللسائق، ولمن يعمل على المكتب أو في المطبخ والورشة والمناوبات. خطوات واقعية تساعدك وتساعد فريقك.</p></section><section class="panel"><h2>الوقاية مسؤولية مشتركة</h2><p>تغيير وضع الجسم والاستراحة والحماية يفيد، لكنه لا يعوض بيئة عمل آمنة وماءً وتهوية ومعدات وتدريبًا مناسبًا. اتفقوا على تحسين ممكن وراجعوا أثره لاحقًا.</p></section><div class="cards">${R.workerIds.map(id=>card(byId[id])).join('')}</div><section class="panel"><h2>فكرة بسيطة للدوام القادم</h2><p>اختر درسًا يناسب عملك، وطبّق تغييرًا واحدًا آمنًا ثم عد لسؤال المتابعة. لا تكتب اسم صاحب العمل أو بيانات صحية شخصية في الاستبيان العام.</p><a class="button" href="#library">المكتبة والمراجع العربية</a></section>`;}
function kidsPage(){return `<section class="kids-welcome panel"><span class="label">للأطفال 6–12 سنة · الأصغر مع بالغ</span><h1>أتعلم وأحمي صحتي وبيئتي</h1><p>مرحبًا! اختر صورة، اقرأ حكاية قصيرة، ثم جرب تصرفًا يساعدك ويساعد أصدقاءك.</p><p>يمكنك الضغط على «استمع للموضوع». وإذا وجدت شيئًا صعبًا، اسأل شخصًا بالغًا تثق به.</p><div class="choice-row"><a class="button" href="#library">كتب وحكايات مع الأسرة</a><a class="button" href="#topic=head-lice-family">للأهل: خطة التعامل مع القمل</a></div></section><section class="kids-grid cards">${R.kidsIds.map(id=>card(byId[id])).join('')}</section><section class="panel"><h2>للأهل والمعلمات</h2><p>درس واحد وموقف واحد في كل مرة. نكيف النشاط لعمر الطفل وقدرته، دون إحراج أو تشخيص أو طلب بياناته. التعليقات والقياس اختيارية، ويُفضل أن يساعد بالغ الأطفال الأصغر.</p><a class="button" href="#classroom">قصص وأنشطة للصف</a></section>`;}
function home(){return `<section class="hero-v2"><div class="hero-photo"><img src="assets/community-hero-arm-support.webp" alt="صورة تخيلية لممرض شاب يسند ذراع رجل مسن أثناء سيرهما، يظهران من الخلف دون الوجهين" width="1536" height="1024" fetchpriority="high"></div><div class="hero-copy"><span class="eyebrow">تمريض من أجل المجتمع</span><h1 class="solidarity-headline">الوعي والسلوك المجتمعي<br>هو خط الدفاع الأول</h1><p>نحوّل المعرفة إلى عادات صحية، ونرعى الإنسان والبيئة بروح التكافل.</p><a class="button primary" href="#explore">ابدأ من موضوع يهمك ←</a><a class="hero-sim-link" href="#simulations">أو جرب موقفًا تفاعليًا ←</a></div></section>${trialNotice()}<section class="student-intro"><div><b>معرفة موثوقة بلغة تصل إلى الجميع</b><p>نُبسّط المعلومة العلمية عمدًا لتناسب فئات المجتمع المختلفة، مع الحفاظ على أسسها العلمية والاستناد إلى مصادر موثوقة تجدها تحت كل موضوع.</p><p>تهدف مبادرة كلية التمريض بجامعة طبرق إلى تعزيز الوعي والسلوك المجتمعي وحماية الصحة والبيئة، وتفعيل الدور التوعوي لطلاب التمريض بإشراف قسم خدمة المجتمع وأساتذتهم. وهي جهود ذاتية دون دعم مادي.</p></div><a class="button soft" href="#feedback">رأيك جزء من تطوير المبادرة</a></section><section class="panel" aria-labelledby="awarenessScope"><h2 id="awarenessScope">توعية عامة تراعي اختلاف الناس</h2><p>هذه المبادرة لا تقدم خدمات طبية أو تشخيصًا أو علاجًا فرديًا، ولا تغني عن مراجعة المختصين. لكل شخص خصوصيته الصحية؛ فما يناسب إنسانًا قد لا يناسب غيره، بحسب العمر والحالة الصحية والأمراض والأدوية والظروف الفردية. لا تغيّر علاجك أو جرعاتك اعتمادًا على معلومة عامة.</p></section>${nursingRoleIntro()}<section class="panel"><h2>عملك يستحق صحة أفضل</h2><p>وقوف طويل، قيادة، مكتب، شاشات أو مناوبات؟ اختر دليلًا يناسب يومك.</p><a class="button primary" href="#workers">صحة العاملين ←</a></section><section class="kids-welcome panel"><h2>للأطفال: أتعلم وأحمي صحتي وبيئتي</h2><p>الماء والنظافة والطعام وأصدقائي في المدرسة… دروس قصيرة بلغتي وأنشطة أجربها مع بالغ.</p><a class="button primary" href="#kids">ادخل ركن الأطفال ←</a></section><section id="explore"><div class="section-title"><div><span class="label">كل المجالات أمامك</span><h2>اختر موضوع صحتك</h2></div><span class="muted">${ARTICLES.length} موضوعًا مصورًا</span></div>${healthHubs()}<details class="audience-paths"><summary>أو اختر من حياتك اليومية: البيت، المدرسة، الأسرة…</summary><div class="life-paths"><button data-path="all" aria-pressed="${pathFilter==='all'}">كل الموضوعات</button>${R.paths.map(p=>`<button data-path="${p[0]}" aria-pressed="${pathFilter===p[0]}"><b>${p[1]}</b><small>${p[2]}</small></button>`).join('')}</div></details><div class="search-tools"><div class="searchbox"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="ابحث بكلمة أو سؤال" placeholder="اكتب: السكري، الضغط، الكلى، صحة المرأة…" value="${esc(query)}"><button id="clearSearch" aria-label="مسح البحث">مسح</button></div><label class="category-select" for="category">أو اختر مجالًا<select id="category"><option value="all">جميع المجالات</option><optgroup label="وصول مباشر">${R.healthHubs.filter(h=>h.ids).map(h=>`<option value="${h.value}" ${category===h.value?'selected':''}>${h.label}</option>`).join('')}</optgroup><optgroup label="المجالات الصحية">${C.categories.map(c=>`<option value="${c[0]}" ${c[0]===category?'selected':''}>${c[1]}</option>`).join('')}</optgroup></select></label></div><div id="categoryGuide"></div><div class="results-head" id="resultsStart"><a href="#explore">تغيير المجال ↑</a><span id="resultCount" role="status" aria-live="polite"></span><button id="allTopics">عرض الجميع</button></div><div id="cards" class="cards"></div><div class="more-wrap"><button id="loadMore" class="button" hidden>موضوعات أكثر ↓</button></div></section>${simulationTeaser()}<section class="featured-tool"><div><span class="label">استعد قبل الحاجة</span><h2>الغرق والحوادث والاختناق والإنعاش</h2><p>فرق بين الغصة وفقد الوعي، وتعلم التصرف الأول في البيت والطريق والرياضة. في طبرق تُوجَّه الحالات الخطرة إلى الحوادث والطوارئ بمركز طبرق الطبي.</p><div class="choice-row"><a class="button primary" href="#urgent">دليل الحالات العاجلة</a><a class="button" href="#topic=unconscious-airway">حقيقة ابتلاع اللسان</a></div></div><div>${Art.render("cpr-aed","رمز الاستعداد للإنعاش وطلب الإسعاف")}</div></section><section class="featured-tool"><div><span class="label">اقرأ من المصدر</span><h2>مكتبة عربية موثوقة</h2><p>${window.CommunityArabicLibrary.length} مصدرًا عربيًا رسميًا و${window.CommunityClassroomStories.length} قصة ونشاطًا للطفل، مع بحث حسب العمر ونوع المادة.</p><a class="button primary" href="#library">افتح المكتبة العربية ←</a><a class="button" href="#classroom">للمعلمة والروضة والمدرسة</a></div><div><a class="button" href="#install-help">كيف أضيف التطبيق إلى هاتفي؟</a></div></section><section id="bloodDonationFeature" class="featured-tool blood-feature"><div><span class="label">التكافل الذي يصل إلى حياة إنسان</span><h2>التبرع بالدم: استعداد آمن ومشاركة طوعية</h2><p>قد يحتاج الدمَ مصابٌ أو مريضٌ في رحلة علاجه. تعرّف إلى الاستعداد للتبرع، والتقييم في مركز الدم، والعناية بعده.</p><div class="choice-row"><a href="#topic=blood-donation" class="button primary">تعرف إلى التبرع بالدم</a><a href="#topic=blood-after" class="button">بعد التبرع</a></div></div><div>${Art.render('blood','رسم توضيحي للتبرع الطوعي بالدم')}</div></section><section class="featured-tool"><div><span class="label">جرب شيئًا عمليًا الآن</span><h2>هل صيدلية البيت مرتبة وآمنة؟</h2><p>تفقد بسيط للأدوات والصلاحية وطريقة الحفظ. يمكنك إعادته كلما احتجت.</p><a href="#topic=home-kit" class="button primary">افتح قائمة التفقد</a></div><div>${Art.render('kit','رسم لمستلزمات صيدلية المنزل')}</div></section><section class="help-strip"><div><h2>هناك علامات لا تنتظر</h2><p>فقد الوعي، ضيق النفس الشديد، ألم الصدر أو نزف شديد: اطلب المساعدة فورًا.</p></div><a class="button" href="#urgent">اعرف كيف تطلب المساعدة</a></section>`}
function results(){const terms=normalize(query).split(/\s+/).filter(Boolean);let list=ARTICLES.filter(a=>(pathFilter==='all'||a.tags.includes(pathFilter))&&(category==='all'||(R.healthHubs.find(h=>h.value===category)?.ids?.includes(a.id))||a.cat===category||(a.alsoCats||[]).includes(category))&&terms.every(t=>normalize([articleText(a),cats[a.cat][1],R.searchAliases[a.id]||'',a.id==='h-pylori'?'بكتيريا المعدة الميكروب الحلزوني':''].join(' ')).includes(t)));if(!query)list.sort((a,b)=>(featured.includes(a.id)?featured.indexOf(a.id):-1+999)-(featured.includes(b.id)?featured.indexOf(b.id):-1+999));if($('#categoryGuide'))$('#categoryGuide').innerHTML=['mother','hub:newborn'].includes(category)?maternalGuide():'';$('#cards').innerHTML=list.length?list.slice(0,visible).map(card).join(''):'<div class="empty"><h2>لم نجد نتيجة بهذه الكلمات</h2><p>جرب كلمة أبسط أو اعرض كل الموضوعات.</p></div>';$('#resultCount').textContent=`${category==='all'?'كل المجالات':(R.healthHubs.find(h=>h.value===category)?.label||cats[category]?.[1]||'الموضوعات')} · ${list.length} موضوعًا${query?' يطابق بحثك':''} · المعروض ${Math.min(visible,list.length)}`;$('#loadMore').hidden=list.length<=visible;document.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.path===pathFilter));document.querySelectorAll('[data-health-hub]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.healthHub===category));}
function articleText(a){return [a.title,a.hook,...(a.emergencyNotice?[a.emergencyNotice]:[]),'الفكرة ببساطة',a.about,'ما الذي تلاحظه؟',...a.symptoms,'خطوات يمكنك فعلها',...a.actions,'للوقاية',...a.prevention,...(a.learningSections||[]).flatMap(s=>[s.title,s.body||'',...(s.bullets||[])]),'عن العلاج والرعاية',a.treatment,'تجنب',a.avoid,'متى تطلب المساعدة؟',a.warning,'مثال من الحياة',a.scene].join('. ')}
function kitTool(){const checked=readLocal('nur-community-kit',[]);return `<section class="interactive-block"><span class="label">قائمة قابلة للتكرار</span><h2>تفقد صيدلية البيت</h2><p>ضع علامة أمام ما تحققت منه. تحفظ العلامات على جهازك، ولا ترسل إلى الكلية.</p><div class="checklist">${R.kit.map((s,i)=>`<label><input type="checkbox" data-kit="${i}" ${Array.isArray(checked)&&checked.includes(i)?'checked':''}><span>${s}</span></label>`).join('')}</div><div class="tool-actions"><button id="kitDone" class="button primary">أنهيت التفقد اليوم</button><button id="kitReset">بدء تفقد جديد</button></div><p id="kitStatus" role="status">${esc(readLocal('nur-community-kit-date','')?'آخر تفقد على هذا الجهاز: '+readLocal('nur-community-kit-date',''):'أعد التفقد دوريًا وبعد استخدام الأدوات.')}</p></section>`}
function waterTool(){return `<section class="interactive-block"><h2>اجعل الماء في طريقك</h2><p>اختر تذكيرًا يوميًا يناسبك، دون فرض كمية لا تلائم حالتك.</p><div class="choice-row">${['مع الوجبات','في استراحة العمل','عند العودة من مشوار'].map(s=>`<button data-water="${s}" aria-pressed="false">${s}</button>`).join('')}</div><p id="waterChoice" role="status">هذا اختيار لهذه الصفحة؛ لا ينشئ تنبيهًا ولا يغير تقييد السوائل الموصوف.</p></section>`}
function topic(id){const a=byId[id];if(!a)return '<div class="empty"><h1>هذا الموضوع غير موجود</h1><a href="#home">العودة للبداية</a></div>';activeTopic=id;return `<article class="article-v2 ${a.childLesson?'child-lesson':''}"><a class="back" href="${a.childLesson?'#kids':'#home'}">→ ${a.childLesson?'ركن الأطفال':'الموضوعات'}</a><div class="topic-hero"><div><span class="label">${esc(cats[a.cat][1])}</span><h1>${esc(a.title)}</h1><p class="topic-hook">${esc(a.hook)}</p><div class="article-actions"><button class="button primary" id="readTopic">◖ استمع للموضوع</button>${star(id)}<button id="share" data-id="${id}">شارك</button><button id="showSources" class="quiet-source-button">مصادر المعلومات</button></div><p class="audience">${esc(a.audience)} · قراءة نحو ${Math.max(2,Math.ceil(articleText(a).split(/\s+/).length/110))} دقائق</p></div><div class="topic-art">${Art.render(a.art,a.title)}</div></div>${a.emergencyNotice?localCarePanel():''}${a.emergencyNotice?`<aside class="warning-block first-aid-notice"><h2>عند الطوارئ الآن</h2><p>${esc(a.emergencyNotice)}</p></aside>`:''}${diabetesShortcuts(a)}<div class="early-measure"><span>تريد مقارنة فهمك قبل القراءة وبعدها؟ المشاركة اختيارية.</span><a href="#measure=${id}&stage=before">ابدأ بسؤال قصير ←</a></div><div id="readable"><section class="intro-text"><h2>الفكرة ببساطة</h2><p>${esc(a.about)}</p>${sectionRefs(a,'about')}</section><div class="topic-grid"><section class="article-block signs"><span class="section-number">01</span><h2>ما الذي قد تلاحظه؟</h2>${listHTML(a.symptoms)}${sectionRefs(a,'symptoms')}</section><section class="article-block actions"><span class="section-number">02</span><h2>خطوات يمكنك فعلها</h2><ol>${a.actions.map(s=>'<li>'+esc(s)+'</li>').join('')}</ol>${sectionRefs(a,'actions')}</section></div><section class="prevention-block"><div>${Art.render(a.art==='cleaning'?'hands':a.art==='stomach'?'foodsafe':a.art,'رسم مرتبط بالوقاية')}</div><div><span class="label">الوقاية والسلوك اليومي</span><h2>ما الذي يقلل الخطر؟</h2>${listHTML(a.prevention)}${sectionRefs(a,'prevention')}</div></section>${learningSections(a)}<section class="treatment-block"><span class="label">معلومة تساعدك على فهم الرعاية</span><h2>${a.childLesson?'إذا احتجت مساعدة':'عن العلاج'}</h2><p>${esc(a.treatment)}</p>${sectionRefs(a,'treatment')}</section><div class="topic-grid"><section class="avoid-block"><h2>انتبه لهذا التصرف</h2><p>${esc(a.avoid)}</p>${sectionRefs(a,'avoid')}</section><section class="warning-block"><h2>متى تطلب المساعدة؟</h2><p>${esc(a.warning)}</p>${sectionRefs(a,'warning')}</section></div><section class="life-scene"><span class="label">من الحياة اليومية</span><h2>موقف قد يحدث عندنا</h2><p>${esc(a.scene)}</p>${sectionRefs(a,'scene')}</section></div>${a.tool==='kit'?kitTool()+sectionRefs(a,'actions'):a.tool==='water'?waterTool()+sectionRefs(a,'actions'):''}${relatedTopics(a)}<section class="next-action"><div><h2>ما الخطوة التي ستأخذها معك؟</h2><p>تأكد من فهم الفكرة، أو أخبرنا إن لم تكن واضحة. يمكنك العودة والمشاركة أكثر من مرة.</p></div><div class="choice-row"><a class="button primary" href="#measure=${id}&stage=after">تأكد من فهمك</a><a class="button" href="#measure=${id}&stage=followup">شارك ما طبقته لاحقًا</a><a class="button" href="#feedback=${id}">ملاحظة أو تصحيح</a></div></section><details class="source-details" id="topicSources"><summary>المصادر وحالة المراجعة</summary><ul class="source-list">${articleSourceKeys(a).map(k=>SOURCES[k]).filter(Boolean).map(s=>`<li><a href="${esc(s[2])}" target="_blank" rel="noopener noreferrer">${esc(s[0])} · ${esc(s[1])} ↗</a></li>`).join('')}</ul><p>إصدار ${R.version} · إعداد وتحقق من الروابط ${R.date}. المعلومات للتوعية العامة، والمصادر العلمية متاحة للاطلاع. تُراجع الإضافات والتحديثات قبل نشرها وتُوثق المساهمات بأسماء أصحابها بعد موافقتهم.</p></details><div class="article-actions"><button id="print">طباعة الموضوع</button><a class="button" href="#home">موضوع آخر</a></div></article>`}
function urgent(){const x=R.localCare;return `<div class="page-head"><h1>عند الخطر: اطلب العون وابدأ التصرف</h1><p>لا تنتظر استكمال قراءة التطبيق عند وجود حالة طارئة.</p></div>${localCarePanel()}<div class="warning-block urgent-large"><h2>لا يستجيب ولا يتنفس طبيعيًا؟</h2><p>${esc(x.resuscitation)}</p><a class="button" href="#topic=adult-cpr">إنعاش البالغ</a><a class="button" href="#topic=child-infant-cpr">إنعاش الطفل والرضيع</a></div><div class="topic-grid"><section class="article-block"><h2>نقسم الأدوار بسرعة</h2><ol><li>شخص يبقى مع المصاب ويبدأ المساعدة اللازمة.</li><li>آخر يرتب النقل والرعاية ويشرح الموقع وما حدث.</li><li>نجهز وقت بدء الأعراض وأسماء الأدوية والحساسية دون تأخير.</li><li>للإصابات الرضية: لا تحرك المصاب بلا ضرورة؛ أولوية الأمان ومجرى التنفس والإنعاش، واطلب مساعدة مؤهلة للنقل إن أمكن.</li></ol></section><section class="article-block"><h2>مرض غير طارئ أم خطر الآن؟</h2><p>${esc(x.routine)}</p><p>لا تدخل مكانًا به كهرباء أو نار أو غاز مؤذٍ دون تأمينه.</p></section></div>${referenceDetails([SOURCES.aidAdult25,SOURCES.aidChild25,SOURCES.aidFirst25],'مراجع الإسعافات والإنعاش — 2025')}<div class="cards">${['adult-cpr','child-infant-cpr','unconscious-airway','choking-adult-child','infant-choking','drowning-rescue','road-accident-first-aid','home-accident-safety','sports-injury-first-aid','poisoning-first-aid','stroke','heart-attack-signs','bleeding','burns','heat','maternal-danger','child-dehydration'].map(id=>card(byId[id])).join('')}</div>`}
function localCarePanel(){const x=R.localCare;return `<aside class="warning-block local-care"><h2>${esc(x.title)}</h2><p>${esc(x.body)}</p></aside>`;}

function measurePage(id,stage){const a=byId[id];if(!a)return '<div class="empty">اختر موضوعًا أولًا. <a href="#home">الموضوعات</a></div>';const n=measurement.rows.filter(r=>r.topic===id).length;return `<div class="narrow"><a class="back" href="#topic=${id}">→ العودة للموضوع</a><div class="page-head"><span class="label">دقيقة اختيارية للفهم والمتابعة</span><h1>${stage==='followup'?'ماذا طبقت بعد القراءة؟':'تأكد من الفكرة الأساسية'}</h1><p>${esc(a.title)}. يمكنك تكرار المشاركة في زيارة أخرى أو بعد نشاط جديد.</p></div><form id="measureForm" class="panel form-panel" data-topic="${id}"><label class="field" for="measureStage">متى تشارك؟</label><select id="measureStage" name="stage"><option value="before" ${stage==='before'?'selected':''}>قبل قراءة الموضوع</option><option value="after" ${stage==='after'?'selected':''}>بعد قراءة الموضوع</option><option value="followup" ${stage==='followup'?'selected':''}>متابعة لاحقة بعد فرصة للتطبيق</option></select><fieldset><legend>${esc(a.question[0])}</legend>${a.question[1].map((s,i)=>`<label class="radio-choice"><input type="radio" name="answer" value="${i}" required><span>${esc(s)}</span></label>`).join('')}</fieldset><label class="field" for="confidence">ما مدى ثقتك بفهم التصرف الصحيح؟</label><select id="confidence" name="confidence" required><option value="">اختر</option><option value="1">ما زلت غير متأكد</option><option value="2">فهمت جزءًا وأحتاج توضيحًا</option><option value="3">أستطيع شرح الفكرة لشخص آخر</option></select><label class="field" for="behavior">وبالنسبة إلى خطوة عملية من الموضوع؟</label><select id="behavior" name="behavior" required><option value="">اختر</option><option value="plan">أنوي تطبيق خطوة</option><option value="done">طبقت خطوة بالفعل</option><option value="notyet">لم أطبق بعد</option><option value="notrelevant">لا تنطبق علي الآن</option></select><label class="field" for="campaign">رمز النشاط إذا أعطاك الفريق رمزًا — اختياري</label><input type="text" id="campaign" name="campaign" maxlength="24" placeholder="اتركه فارغًا عند القراءة الفردية"><label class="consent"><input name="linkPrevious" type="checkbox"> هذه متابعة لإجابتي القبلية السابقة في الموضوع نفسه ورمز النشاط نفسه على هذا الجهاز. اتركها دون تحديد لمشاركة مستقلة.</label><label class="consent"><input name="consent" type="checkbox" required> أوافق على حفظ هذه الإجابة دون اسم على هذا الجهاز. لا ترسل للكلية تلقائيًا.</label><button class="button primary" type="submit">احفظ المشاركة</button><p class="form-note">المحفوظ هنا لهذا الموضوع: ${n} سجلات. لا يوجد قيد «مرة واحدة». لا ترسل الإجابات تلقائيًا ولا تعني عدد أشخاص مختلفين.</p></form><div id="measureResult" aria-live="polite"></div></div>`}
function dashboard(){const s=measurement.summary();return `<div class="page-head"><span class="label">أدوات فريق المبادرة</span><h1>متابعة متكررة على هذا الجهاز</h1><p>الأرقام لهذا المتصفح فقط؛ لا تمثل الوصول العام أو عدد المستفيدين. التصدير متاح من هذا الجهاز؛ تصل إجابات استبيان التجربة إلى فريق المبادرة عبر النموذج المستقل.</p></div><div class="metric-grid"><div><b>${s.records}</b><span>سجل اختياري محفوظ</span></div><div><b>${s.paired}</b><span>دورة لها قياس قبلي وبعدي مطابقان</span></div><div><b>${s.change===null?'—':s.change.toFixed(1)}</b><span>فرق صحة الإجابة بالنقاط المئوية</span></div><div><b>${s.followup?s.action+' / '+s.followup:'—'}</b><span>دورات متابعة أفادت بتطبيق خطوة</span></div></div><section class="panel"><h2>كيف نقرأ النتائج؟</h2><p>تُطابق الإجابات داخل دورة الموضوع ورمز النشاط والإصدار والسؤال نفسه؛ يؤخذ آخر قياس من كل مرحلة. السلوك والثقة بلاغ ذاتي. رؤية الإجابة وتكرار الاختبار يؤثران في التعلم، فلا يفسر الفرق وحده كأثر سببي أو صحي للتطبيق.</p><div class="choice-row"><button id="exportMetrics" class="button primary">تصدير سجل CSV</button><button id="clearMetrics">مسح السجل المحلي</button><a class="button" href="measurement-protocol.md">دليل القياس والتوثيق</a></div><p id="clearMetricsPrompt" role="status"></p></section><details><summary>البيانات المركزية والتوثيق</summary><p>تحفظ سجلات القياس والمحاكاة بإذن على هذا الجهاز، ويمكن تصديرها. أما استبيان التجربة فله نموذج مستقل، وتصل إجاباته إلى فريق المبادرة عند ضغط المشارك على «إرسال». لا ترسل سجلات الجهاز في الخلفية.</p></details><details><summary>إغلاق دورة التحسين ثم إعادة القياس</summary><p>راجع الملاحظات شهريًا: المشكلة والسبب والإجراء والمسؤول والموعد والدليل ثم إعادة القياس. كرر الدورة مع كل حملة، ولا تدمج إصدارات أو جماهير دون بيان. <a href="improvement-register.csv" download>تنزيل سجل تحسين فارغ</a>.</p></details>${simulationDashboard()}${surveyDashboard()}<section class="panel"><h2>سجلات العمل</h2><div class="choice-row"><a class="button" href="activity-record.csv" download>الأنشطة والنتائج الإجمالية</a><a class="button" href="#students">الطلاب والمشرفون</a></div></section>`}
function students(){return `<div class="page-head"><h1>الطلاب والمشرفون</h1><p>اختاروا حاجة حقيقية من أسئلة الناس، وأعدوا محتوى عمليًا، ثم اختبروا وضوحه وحدثوه بناءً على الملاحظات.</p></div><div class="topic-grid"><section class="panel"><h2>دورة عمل مستمرة</h2><ol><li>اسمع الاحتياج وحدد الجمهور.</li><li>راجع مصدرًا رسميًا واكتب مثالًا من الحياة.</li><li>اعرض الدقة وعلامات الخطر على أستاذ مختص.</li><li>اختبر الفهم وأصلح ما التبس.</li><li>سجل المساهمات والموافقة وانشر الإصدار.</li><li>تابع التعلم والسلوك وأعد القياس بعد التحسين.</li></ol></section><section class="panel english" lang="en" dir="ltr"><h2>Students and supervisors</h2><p>Prepare original plain-language education from authoritative sources. Include symptoms, warning signs, prevention, practical actions and safe treatment information. Obtain subject review and publication approval. Credit real contributions only after consent.</p><p>Feedback remains open to repeated contributions. Optional assessments record topic, release, stage, anonymous cycle and campaign code. Local records stay on the device until exported. Feedback is submitted through the dedicated Google Form. Local measurement and simulation records remain on the device until explicitly exported.</p></section></div><section class="panel"><h2>التوثيق والمتابعة</h2><div class="choice-row"><a class="button primary" href="#dashboard">سجل المتابعة على هذا الجهاز</a><a class="button" href="plan.html">خطة البداية</a></div><p>رسم الواجهة تخيلي ولا يمثل طلابًا أو مستفيدين حقيقيين. لا تنشر بيانات مرضى أو صورًا دون موافقات مناسبة.</p></section>`}
function about(){return `${nursingRoleIntro()}<div class="page-head"><h1>عن المبادرة وسهولة الاستخدام</h1><p>جهود ذاتية لطلاب كلية التمريض بجامعة طبرق، بإشراف قسم خدمة المجتمع والأساتذة، لنشر وعي صحي عملي دون دعم مادي.</p></div><section class="panel"><h2>القراءة بصوت</h2><p>اضغط «استمع للموضوع». يعتمد الصوت العربي على أصوات هاتفك أو متصفحك؛ يمكنك اختيار الصوت والسرعة. إن لم يتوفر صوت عربي تظهر رسالة، ويمكن إضافة صوت عربي من إعدادات الجهاز. بعض الأصوات تعمل محليًا وبعضها يحتاج اتصالًا وخدمة الجهاز.</p><h2>إضافة إلى الهاتف</h2><p>في Android اختر التثبيت أو الإضافة إلى الشاشة الرئيسية من قائمة المتصفح. في Safari على iPhone: مشاركة ثم إضافة إلى الشاشة الرئيسية. بعد التحميل الكامل تتاح المواد والرسوم المضمنة دون اتصال؛ روابط المصادر الخارجية تحتاج اتصالًا.</p><h2>خصوصيتك واختياراتك</h2><p>المفضلة وحجم الخط وتفقد الصيدلية تبقى على الجهاز. لا نسجل زيارات أو هوية في الخلفية. سجلات القياس والمحاكاة تحفظ بموافقتك على جهازك فقط، والتصدير اختياري. استبيان التجربة مستقل ويستخدم نماذج Google؛ تُرسل الإجابات عند ضغطك على «إرسال» داخله. قد يحتفظ المضيف بسجلات تشغيله المعتادة.</p><button id="resetPreferences">مسح المفضلة وإعدادات النص</button><h2>المحتوى والمراجعة</h2><p>لكل مادة مصادر وحالة مراجعة. المعلومات تشرح الوقاية والرعاية والعلاج العام ولا تحدد وصفة أو جرعة شخصية. تُراجع كل إضافة أو تحديث قبل نشره. النسخة التجريبية لاختبار التقنية وسهولة الاستخدام وتلقي آراء المجتمع.</p></section><div class="choice-row"><a class="button" href="#feedback">نقد أو اقتراح</a><a class="button" href="#students">الطلاب والمشرفون</a><a class="button" href="#dashboard">أدوات المتابعة</a></div>`}
function route(){stopReading();let h=location.hash.slice(1)||'home';const params=new URLSearchParams(h),topicId=params.get('topic'),feedbackId=params.get('feedback'),measureId=params.get('measure'),simId=params.get('sim'),storyId=params.get('story');if(h==='classroom'){libraryAudience='teacher';libraryKind='all';libraryQuery='';libraryCategory='all';libraryVisible=12;}const key=storyId?'story':h==='classroom'?'library':simId?'sim':topicId?'topic':h.startsWith('feedback')?'feedback':measureId?'measure':h==='explore'?'home':h;activeTopic=null;const main=$('#main');if(key!=='sim')simulationRun=null;main.innerHTML=key==='story'?classroomStoryPage(storyId):key==='sim'?simulationPage(simId):key==='simulations'?simulationLibrary():key==='workers'?workersPage():key==='kids'?kidsPage():key==='library'?arabicLibraryPage():key==='install-help'?installHelp():key==='topic'?topic(topicId):key==='feedback'?feedback(feedbackId):key==='measure'?measurePage(measureId,params.get('stage')||'after'):key==='urgent'?urgent():key==='saved'?`<div class="page-head"><h1>موضوعاتك المحفوظة</h1><p>يمكنك الرجوع إليها من هذا الجهاز.</p></div><div class="cards">${saved.map(id=>card(byId[id])).join('')||'<div class="empty">اضغط النجمة ☆ على أي موضوع لحفظه هنا.</div>'}</div>`:key==='about'?about():key==='students'?students():key==='dashboard'?dashboard():home();document.querySelectorAll('[data-nav]').forEach(a=>{a.removeAttribute('aria-current');if(a.dataset.nav===(key==='topic'?'home':key==='story'?'library':key==='sim'?'simulations':key))a.setAttribute('aria-current','page')});if(!['workers','kids','story','library','install-help','sim','simulations','topic','feedback','measure','urgent','saved','about','students','dashboard'].includes(key))results();document.title=(storyById[storyId]?storyById[storyId].title+' | ':scenarioById[simId]?scenarioById[simId].title+' | ':byId[topicId]?byId[topicId].title+' | ':'')+'تمريض من أجل المجتمع';if(h==='explore')$('#explore')?.scrollIntoView();else window.scrollTo(0,0);if(key==='library')arabicLibraryResults();if(key==='simulations')scenarioSearchResults();main.focus({preventScroll:true});}
let speechChunks=[],speechIndex=0,speechActive=false,speechPaused=false,voices=[],speechEpoch=0;
function loadVoices(){if(!('speechSynthesis'in window))return;voices=window.speechSynthesis.getVoices().filter(v=>/^ar(?:[-_]|$)/i.test(v.lang));const s=$('#voice');if(s){const chosen=s.value;s.innerHTML=voices.map((v,i)=>`<option value="${i}">${esc(v.name)}${v.localService?' · على الجهاز':''}</option>`).join('');if(chosen&&voices[chosen])s.value=chosen;}}
function stopReading(){speechEpoch++;if('speechSynthesis'in window)window.speechSynthesis.cancel();speechActive=false;speechPaused=false;speechChunks=[];speechIndex=0;const p=$('#audioPlayer');if(p)p.hidden=true;const surveyButton=$('#surveyLauncher');if(surveyButton)surveyButton.hidden=false;}
function playChunk(){if(!speechActive||!speechChunks[speechIndex]){stopReading();return}const voice=voices[Number($('#voice').value)||0];if(!voice){stopReading();notify('لا يوجد صوت عربي متاح. أضف صوتًا عربيًا من إعدادات النطق.');return}const token=speechEpoch,u=new window.SpeechSynthesisUtterance(speechChunks[speechIndex]);u.voice=voice;u.lang=voice.lang;u.rate=Number($('#speed').value)||.9;u.onend=()=>{if(!speechActive||token!==speechEpoch)return;speechIndex++;if(speechIndex<speechChunks.length)playChunk();else stopReading()};u.onerror=e=>{if(token!==speechEpoch)return;if(['canceled','interrupted'].includes(e.error))return;stopReading();notify('تعذرت القراءة الصوتية. تحقق من الصوت العربي والاتصال إذا كان الصوت يحتاجه.')};$('#audioProgress').textContent=`${speechIndex+1} / ${speechChunks.length}`;window.speechSynthesis.speak(u);}
function startReading(customText,customTitle){if(!activeTopic&&typeof customText!=='string')return;if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){notify('هذا المتصفح لا يوفر القراءة الصوتية. جرب قارئ الشاشة أو متصفحًا داعمًا.');return}loadVoices();if(!voices.length){notify('لا يوجد صوت عربي متاح الآن. أضف صوتًا عربيًا من إعدادات النطق ثم أعد المحاولة.');return}stopReading();const text=typeof customText==='string'?customText:articleText(byId[activeTopic]);speechChunks=[];let chunk='';for(const word of text.split(/\s+/)){if(chunk.length+word.length>160&&chunk){speechChunks.push(chunk);chunk=''}chunk+=(chunk?' ':'')+word;}if(chunk)speechChunks.push(chunk);speechIndex=0;speechActive=true;$('#audioPlayer').hidden=false;const surveyButton=$('#surveyLauncher');if(surveyButton)surveyButton.hidden=true;$('#audioTitle').textContent=customTitle||byId[activeTopic]?.title||'قراءة الموقف';$('#pauseAudio').textContent='إيقاف مؤقت';playChunk();}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;visible=12;results()}});
document.addEventListener('change',e=>{if(e.target.id==='category'){category=e.target.value;pathFilter='all';visible=12;results()}if(e.target.dataset.kit!==undefined){let checked=readLocal('nur-community-kit',[]);if(!Array.isArray(checked))checked=[];const i=Number(e.target.dataset.kit);checked=e.target.checked?[...new Set([...checked,i])]:checked.filter(v=>v!==i);if(!writeLocal('nur-community-kit',checked))notify('التخزين غير متاح؛ العلامات لهذه الزيارة فقط.')}if(['voice','speed'].includes(e.target.id)&&speechActive){speechEpoch++;window.speechSynthesis.cancel();speechPaused=false;$('#pauseAudio').textContent='إيقاف مؤقت';playChunk()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.path){pathFilter=b.dataset.path;category='all';query='';visible=12;$('#category').value='all';$('#search').value='';results()}if(b.dataset.healthHub){category=b.dataset.healthHub;pathFilter='all';query='';visible=12;$('#category').value=category;$('#search').value='';results();$('#resultsStart')?.scrollIntoView({block:'start'});}if(b.id==='loadMore'){visible+=12;results()}if(b.id==='allTopics'){pathFilter='all';category='all';query='';visible=ARTICLES.length;$('#search').value='';$('#category').value='all';results()}if(b.id==='clearSearch'){query='';visible=12;$('#search').value='';results();$('#search').focus()}if(b.dataset.save){const id=b.dataset.save;saved=saved.includes(id)?saved.filter(s=>s!==id):[...saved,id];writeLocal('nur-community-saved',saved);document.querySelectorAll('[data-save="'+id+'"]').forEach(el=>{el.textContent=saved.includes(id)?'★':'☆';el.setAttribute('aria-pressed',saved.includes(id));el.setAttribute('aria-label',(saved.includes(id)?'إزالة من':'إضافة إلى')+' المحفوظات')});if(location.hash==='#saved')route()}if(b.id==='fontSize'){fontLevel=(fontLevel+1)%3;applyFont();writeLocal('nur-community-font-v2',fontLevel)}if(b.id==='readTopic')startReading();if(b.id==='readSimulation')startReading(simulationReadText(),simulationRun?.scenario.title||'المحاكاة');if(b.dataset.simChoice){stopReading();if(simulationRun&&!simulationRun.pending&&!simulationRun.complete){simulationRun.choose(b.dataset.simChoice);renderSimulation();}}if(b.id==='simNext'){stopReading();if(simulationRun?.pending){simulationRun.advance();renderSimulation();}}if(b.id==='simRestart'&&simulationRun){stopReading();simulationRun=new window.CommunitySimulation.Run(simulationRun.scenario);renderSimulation();}if(b.id==='exportSimulations')download('community-simulations-'+new Date().toISOString().slice(0,10)+'.csv',simulationRecords.csv(),'text/csv;charset=utf-8');if(b.id==='clearSimulations')$('#clearSimulationsPrompt').innerHTML='<p>سيُمسح سجل المحاكاة من هذا الجهاز فقط.</p><button id="confirmClearSimulations">تأكيد المسح المحلي</button>';if(b.id==='confirmClearSimulations'){try{simulationRecords.clear();route()}catch{notify('تعذر مسح سجل المحاكاة.')}}if(b.id==='stopAudio')stopReading();if(b.id==='pauseAudio'&&speechActive){speechPaused=!speechPaused;if(speechPaused)window.speechSynthesis.pause();else window.speechSynthesis.resume();b.textContent=speechPaused?'استئناف':'إيقاف مؤقت'}if(b.id==='showSources'){const d=$('#topicSources');if(d){d.open=true;d.scrollIntoView({block:'start'});}}if(b.id==='exportSurvey')download('community-pilot-survey-'+new Date().toISOString().slice(0,10)+'.csv',surveyStore.csv(),'text/csv;charset=utf-8');if(b.id==='clearSurvey')$('#clearSurveyPrompt').innerHTML='<p>سيُمسح السجل المحلي فقط. صدره أولًا إذا احتجته.</p><button id="confirmClearSurvey">تأكيد المسح</button>';if(b.id==='confirmClearSurvey'){try{surveyStore.clear();route()}catch{notify('تعذر مسح السجل المحلي.')}}if(b.id==='print')window.print();if(b.id==='share'){try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else if(navigator.clipboard){await navigator.clipboard.writeText(location.href);notify('نُسخ رابط الموضوع.')}else notify('انسخ الرابط من شريط العنوان.')}catch(err){if(err.name!=='AbortError')notify('يمكنك نسخ الرابط من شريط العنوان.')}}if(b.id==='kitReset'){writeLocal('nur-community-kit',[]);document.querySelectorAll('[data-kit]').forEach(el=>el.checked=false);$('#kitStatus').textContent='بدأ تفقد جديد. لا تتغير الصلاحيات أو شروط الحفظ بمجرد وضع علامة.'}if(b.id==='kitDone'){const date=new Date().toLocaleDateString('ar-LY');writeLocal('nur-community-kit-date',date);$('#kitStatus').textContent='سجلت التفقد على هذا الجهاز بتاريخ '+date+'؛ يمكنك إعادته مجددًا.'}if(b.dataset.water){document.querySelectorAll('[data-water]').forEach(el=>el.setAttribute('aria-pressed',el===b));$('#waterChoice').textContent='اختيارك لهذه الزيارة: '+b.dataset.water+' — اتبع أي تقييد سوائل وصفه فريقك.'}if(b.id==='exportMetrics')download('community-measurements-'+new Date().toISOString().slice(0,10)+'.csv',measurement.csv(),'text/csv;charset=utf-8');if(b.id==='clearMetrics')$('#clearMetricsPrompt').innerHTML='<p>سيُمسح سجل القياس من هذا الجهاز فقط. صدره أولًا إن كنت تحتاجه.</p><button id="confirmClearMetrics">تأكيد المسح المحلي</button>';if(b.id==='confirmClearMetrics'){try{measurement.clear();route()}catch{notify('تعذر مسح السجل على هذا المتصفح.')}}if(b.id==='resetPreferences'){saved=[];fontLevel=0;writeLocal('nur-community-saved',[]);writeLocal('nur-community-font-v2',0);applyFont();notify('مُسحت المفضلة وإعدادات النص. لم يتغير سجل القياس.')}if(b.id==='install'){if(installEvent){const promptEvent=installEvent;installEvent=null;await promptEvent.prompt();}else{location.hash='#install-help';route();}}});
document.addEventListener('submit',e=>{if(e.target.id==='simulationForm'){e.preventDefault();saveSimulation(e.target);}if(e.target.id==='measureForm'){e.preventDefault();const f=new FormData(e.target),a=byId[e.target.dataset.topic];if(!a||!f.get('consent')||f.get('answer')===null)return;const stage=String(f.get('stage')),score=Number(f.get('answer'))===a.question[2]?1:0,campaign=String(f.get('campaign')||'').trim().slice(0,24);let row;try{row=measurement.save({topic:a.id,release:R.version,assessment:a.id+'-q1-v1',stage,score,confidence:String(f.get('confidence')),behavior:String(f.get('behavior')),campaign,linkPrevious:!!f.get('linkPrevious')})}catch{notify('تعذر الحفظ. قد يكون التخزين ممتلئًا أو غير متاح؛ صدّر السجل إذا لزم.');return}$('#measureResult').innerHTML=`<section class="measurement-result"><h2>حُفظت المشاركة على هذا الجهاز</h2><p>${stage==='before'?'اقرأ الموضوع ثم عد للقياس البعدي. لا نعرض الحل في القياس القبلي.':'الفكرة الصحيحة: '+esc(a.question[1][a.question[2]])}</p><p>لم تُرسل للكلية. يمكنك تصدير السجل من أدوات المتابعة.</p><div class="choice-row"><a class="button primary" href="#dashboard">السجل والتصدير</a><a class="button" href="#topic=${a.id}">العودة للموضوع</a><a class="button" href="#measure=${a.id}&stage=${stage==='before'?'after':'followup'}">مشاركة أخرى</a></div><p class="form-note">سجل ${esc(row.id)} · ${new Date(row.time).toLocaleString('ar-LY')}. المشاركة الجديدة لا تُحسب تلقائيًا كشخص جديد.</p></section>`;$('#measureResult').scrollIntoView({block:'center'});}});
function resourceNorm(s){return String(s).normalize('NFKD').replace(/[\u064B-\u065F]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').toLowerCase().trim();}

function installHelp(){return `<section class="page-head"><span class="label">وصول سريع من شاشة هاتفك</span><h1>أضف التطبيق إلى هاتفك</h1><p>التطبيق يعمل من الرابط. على الآيفون تتم الإضافة من قائمة سفاري، وقد لا يظهر إشعار تنزيل تلقائي.</p></section><section class="panel"><h2>آيفون أو آيباد · Safari</h2><ol class="install-steps"><li>افتح رابط التطبيق في <b>Safari / سفاري</b>. إذا وصلتك الصفحة داخل واتساب أو فيسبوك، انسخ الرابط وافتحه في سفاري.</li><li>اضغط <b>المشاركة ↑</b> (مربع وسهم لأعلى). في بعض الإصدارات افتح قائمة الصفحة ثم «مشاركة».</li><li>مرر خيارات المشاركة إلى أسفل واختر <b>إضافة إلى الشاشة الرئيسية / Add to Home Screen</b>.</li><li>إذا ظهر خيار <b>فتح كتطبيق ويب / Open as Web App</b> فعّله، ثم اضغط <b>إضافة / Add</b>.</li><li>ارجع إلى الشاشة الرئيسية واضغط أيقونة شعار الكلية.</li></ol><p>إن لم تجد الخيار: تأكد أنك في سفاري، ومرر قائمة المشاركة كاملة؛ قد يكون تحت «تعديل الإجراءات». تختلف أسماء القوائم قليلًا حسب إصدار الجهاز.</p><a href="https://support.apple.com/ar-bh/guide/iphone/iph42ab2f3a7/ios" target="_blank" rel="noopener noreferrer">شرح Apple الرسمي بالعربية ↗</a></section><section class="panel"><h2>أندرويد · Chrome</h2><p>اضغط «أضف إلى هاتفك» إن ظهر طلب التثبيت، أو افتح قائمة المتصفح ⋮ ثم «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».</p><p>تحتاج اتصالًا في الزيارة الأولى لحفظ المحتوى. روابط المكتبة والاستبيان الخارجي تحتاج اتصالًا بالإنترنت. قد يختصر الهاتف الاسم الطويل تحت الأيقونة.</p><a class="button" href="#home">العودة للموضوعات</a></section>`;}
let libraryQuery='',libraryCategory='all',libraryAudience='all',libraryKind='all',libraryVisible=12,scenarioQuery='';
const libraryKinds={article:'مقال مبسط أو شرح عام',book:'كتاب أو كتيب PDF',video:'فيديو تعليمي',activity:'أفكار وأنشطة',collection:'مجموعة موارد',story:'قصة ونشاط داخل التطبيق'};
const libraryAudiences={public:'الأسر والمجتمع',teacher:'المعلمة والميسر',preschool:'اختيارات للروضة · مع بالغ',primary:'اختيارات للابتدائي · مع بالغ',teen:'المراهقون ومقدمو الرعاية',carer:'مقدمو رعاية كبار السن'};
const storyById=Object.fromEntries(window.CommunityClassroomStories.map(s=>[s.id,s]));
function libraryAllItems(){const stories=window.CommunityClassroomStories.map(s=>({...s,internal:true,description:s.goal,publisher:'كلية التمريض · نص أصلي للمبادرة',level:'قصة قصيرة بلغة الطفل',tip:s.teacherTip}));return [...stories,...window.CommunityArabicLibrary];}
function arabicLibraryCards(){const q=resourceNorm(libraryQuery);return libraryAllItems().filter(x=>(libraryCategory==='all'||x.category===libraryCategory||(libraryCategory==='mental-social'&&['نفسية وسلوك','اجتماعية ومجتمعية'].includes(x.category)))&&(libraryAudience==='all'||x.audiences.includes(libraryAudience))&&(libraryKind==='all'||x.kind===libraryKind)&&(!q||resourceNorm([x.title,x.description,x.category,x.age,x.publisher,libraryKinds[x.kind],x.tip].join(' ')).includes(q)));}
function libraryCard(x){return `<article class="panel library-card">${x.internal?`<a class="library-art" href="#story=${x.id}">${Art.render(x.art,x.title)}</a>`:''}<span class="label">${esc(x.category)} · ${esc(libraryKinds[x.kind])}</span><h2>${esc(x.title)}</h2><p>${esc(x.description)}</p><p class="library-age"><b>${esc(x.age)}</b> · ${esc(x.level)}</p><p class="muted">${esc(x.publisher)}</p><details class="library-tip"><summary>كيف أستفيد من هذه المادة؟</summary><p>${esc(x.tip)}</p></details><div class="choice-row">${x.internal?`<a class="button primary" href="#story=${x.id}">اقرأ القصة ونفذ النشاط ←</a>`:`<a class="button primary" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x.kind==='book'?'افتح الكتيب العربي PDF':'افتح المصدر العربي'} ↗</a>`}<button class="button" data-read-resource="${esc(x.id)}" aria-label="استمع لوصف ${esc(x.title)}">استمع للوصف</button><a class="button" href="#topic=${x.topic}">شرح مرتبط داخل التطبيق</a></div><small>${x.internal?'نص وأنشطة أصلية للمبادرة':'فُحص الرابط واللغة: '+x.checked+' · مصدر خارجي يحتاج إنترنت'}</small></article>`;}
function arabicLibraryResults(){const items=arabicLibraryCards(),shown=items.slice(0,libraryVisible);$('#libraryCount').textContent=items.length+' مادة · يظهر '+shown.length;$('#libraryCards').innerHTML=shown.map(libraryCard).join('')||'<div class="empty"><p>لم نجد مادة بهذه الاختيارات. جرّب كلمة أخرى أو امسح المرشحات.</p><button id="resetLibrary" class="button">عرض كل المكتبة</button></div>';$('#libraryMore').hidden=shown.length>=items.length;}
function librarySelect(id,label,options,value){return `<label class="category-select" for="${id}">${label}<select id="${id}"><option value="all">الجميع</option>${Object.entries(options).map(([k,t])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function arabicLibraryPage(){const external=window.CommunityArabicLibrary.length,stories=window.CommunityClassroomStories.length;return `<section class="page-head"><span class="label">الصحة جسد ونفس وعلاقات وبيئة</span><h1>مكتبة المعرفة والحكايات</h1><p><b>${external} مصدرًا عربيًا رسميًا + ${stories} قصة ونشاطًا أصليًا داخل التطبيق.</b> كتب وكتيبات وشروح وفيديوهات وأفكار للعب. الوصف مكتوب ببساطة لتختار ما يناسبك؛ بعض المراجع الخارجية أكثر تفصيلًا وموجهة للكبار.</p></section><section class="classroom-feature panel"><div><span class="label">للمعلمة والأهل</span><h2>حلقة قراءة صغيرة… وفكرة تبقى</h2><p>اختاري قصة قصيرة، اقرئيها أو شغلي صوتها، ثم سؤالين ونشاطًا آمنًا. الأعمار إرشادية ونكيف النشاط لقدرات الطفل؛ أدلة الميسرين تحتاج تحضيرًا ولا تُقرأ كلها للروضة.</p></div><div class="choice-row"><button class="button primary" data-library-preset="stories">قصص جاهزة للقراءة</button><button class="button" data-library-preset="teacher">مواد المعلمة والميسر</button><button class="button" data-library-preset="preschool">للروضة مع بالغ</button></div></section><div class="library-shortcuts choice-row"><button data-library-preset="mental">نفسية واجتماعية</button><button data-library-preset="environment">البيئة والماء</button><button data-library-preset="brain">الدماغ والأعصاب</button><button data-library-preset="firstaid">الإسعاف والإنعاش</button><button data-library-preset="teen">الأسرة والمراهقون</button><button id="resetLibrary">كل المكتبة</button></div><div class="search-tools library-filters"><label class="searchbox" for="librarySearch">ابحث في المكتبة<input type="search" id="librarySearch" value="${esc(libraryQuery)}" placeholder="قصة، تنمر، باركنسون، ماء، ذاكرة…"></label>${librarySelect('libraryCategory','المجال',{...Object.fromEntries([...new Set(libraryAllItems().map(x=>x.category))].map(x=>[x,x])),'mental-social':'نفسية واجتماعية معًا'},libraryCategory)}${librarySelect('libraryAudience','لمن أبحث؟',libraryAudiences,libraryAudience)}${librarySelect('libraryKind','نوع المادة',libraryKinds,libraryKind)}</div><p id="libraryCount" role="status" aria-live="polite"></p><div id="libraryCards" class="cards"></div><div class="more-wrap"><button id="libraryMore" class="button" hidden>مواد أكثر ↓</button></div><section class="panel"><h2>اقرأ المصدر واعرف سياقه</h2><p>روابط القراءة الخارجية تحتاج إنترنت. بعض الكتب ملفات PDF تحتاج وقتًا للتحميل. أرقام الطوارئ داخل المراجع الخارجية تخص بلدانها؛ في طبرق راجع مسار الوصول إلى الحوادث والطوارئ داخل التطبيق، ولا تفترض توفر سيارة إسعاف. النصوص الأصلية لدينا ليست صادرة عن المنظمات المرتبطة، ومصادرها تدعم المبادئ العامة. الأنشطة لا تشخص الأطفال ولا تستبدل دعم المختص عند الحاجة.</p><a href="#feedback">اقترح مصدرًا أو اكتب نقدًا؛ يمكن المشاركة أكثر من مرة</a></section>`;}
function applyLibraryPreset(preset){libraryQuery='';libraryCategory='all';libraryAudience='all';libraryKind='all';libraryVisible=12;if(preset==='stories'){libraryAudience='teacher';libraryKind='story';}if(['teacher','preschool'].includes(preset))libraryAudience=preset;if(preset==='environment')libraryCategory='الصحة والبيئة';if(preset==='brain')libraryCategory='الدماغ والأعصاب';if(preset==='firstaid')libraryCategory='إسعاف وتكافل';if(preset==='teen')libraryAudience='teen';if(preset==='mental')libraryCategory='mental-social';$('#main').innerHTML=arabicLibraryPage();arabicLibraryResults();$('#libraryCount').scrollIntoView({block:'start'});}
function classroomStoryText(s){return [s.title,...s.paragraphs].join('. ');}
function classroomStoryPage(id){const s=storyById[id];if(!s)return '<div class="empty"><h1>هذه القصة غير موجودة</h1><a href="#classroom">ارجع للقصص</a></div>';return `<article class="classroom-story"><a class="back" href="#classroom">→ مكتبة المعلمة والطفل</a><div class="sim-heading"><div><span class="label">نص أصلي للمبادرة · قراءة مع بالغ</span><h1>${esc(s.title)}</h1><p>${esc(s.age)} · ${s.minutes} · ${esc(s.goal)}</p><div class="choice-row"><button class="button primary" data-read-story="${s.id}">استمع للقصة</button><button class="button" id="print">اطبع القصة والنشاط</button></div></div><div class="sim-art">${Art.render(s.art,s.title)}</div></div><section class="story-narrative" aria-label="القصة">${s.paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}</section><section class="panel"><h2>لنتحدث معًا</h2><ul>${s.questions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>المشاركة اختيارية؛ يمكن للطفل الإشارة أو الرسم أو الاستماع فقط.</p></section><section class="panel"><h2>نشاط بسيط بعد القراءة</h2><ol>${s.activity.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><details open><summary>ملاحظة للمعلمة أو ولي الأمر</summary><p>${esc(s.teacherTip)}</p></details></section><details class="source-details"><summary>المصادر وفكرة النشاط</summary><p>القصة والأنشطة نصوص أصلية للمبادرة، وليست اقتباسًا أو إصدارًا من الجهات التالية. هذه مراجع للمبادئ العامة؛ الأعمار المقترحة إرشادية، وتُكيف الأنشطة لقدرات الأطفال وبإشراف بالغ.</p><ul>${s.sources.map(id=>window.CommunityArabicLibrary.find(x=>x.id===id)).filter(Boolean).map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.publisher)} · ${esc(x.title)} ↗</a></li>`).join('')}</ul></details><div class="choice-row"><a class="button" href="#topic=${s.topic}">شرح للكبار عن الموضوع</a><a class="button" href="#feedback=${s.id}">رأيك في القصة والنشاط</a><a class="button" href="#classroom">اختر قصة أخرى</a></div></article>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.libraryPreset)applyLibraryPreset(b.dataset.libraryPreset);if(b.id==='readNursingRole'){const x=R.nursingRole;startReading([x.title,x.intro,x.examples,x.scope].join('. '),x.title);}if(b.id==='resetLibrary')applyLibraryPreset('all');if(b.id==='libraryMore'){libraryVisible+=12;arabicLibraryResults();}if(b.dataset.readStory){const s=storyById[b.dataset.readStory];if(s)startReading(classroomStoryText(s),s.title);}if(b.dataset.readResource){const x=libraryAllItems().find(x=>x.id===b.dataset.readResource);if(x)startReading([x.title,x.description,x.age,x.tip].join('. '),x.title);}});
function scenarioSearchResults(){const q=resourceNorm(scenarioQuery),items=window.CommunityScenarios.items.filter(s=>!q||resourceNorm(s.title+' '+s.intro+' '+s.topics.map(id=>byId[id]?.title||'').join(' ')).includes(q));$('#scenarioCards').innerHTML=items.map(simulationCard).join('')||'<p class="empty">لا يوجد موقف بهذا البحث. جرّب كلمة مثل السكري أو الحرق.</p>';$('#scenarioCount').textContent=items.length+' موقفًا';}
document.addEventListener('input',e=>{if(e.target.id==='librarySearch'){libraryQuery=e.target.value;libraryVisible=12;arabicLibraryResults();}if(e.target.id==='scenarioSearch'){scenarioQuery=e.target.value;scenarioSearchResults();}});
document.addEventListener('change',e=>{if(e.target.id==='libraryCategory')libraryCategory=e.target.value;if(e.target.id==='libraryAudience')libraryAudience=e.target.value;if(e.target.id==='libraryKind')libraryKind=e.target.value;if(['libraryCategory','libraryAudience','libraryKind'].includes(e.target.id)){libraryVisible=12;arabicLibraryResults();}});

function simulationCard(s){return `<article class="story-card sim-card"><a class="card-art" href="#sim=${s.id}">${Art.render(s.art,s.title)}</a><div class="card-copy"><span class="label">موقف متفرع · بلا مؤقت</span><h3><a href="#sim=${s.id}">${esc(s.title)}</a></h3><p>${esc(s.intro)}</p><a class="button soft" href="#sim=${s.id}">جرّب قرارك ←</a></div></article>`;}
function simulationTeaser(){return `<section class="simulation-teaser"><div class="section-title"><div><span class="label">تعلم بالموقف والاختيار</span><h2>ماذا ستفعل لو حدث هذا؟</h2><p>اختر تصرفًا، وافهم نتيجته، ثم أكمل الموقف. يمكنك إعادة المحاولة.</p></div><a class="button" href="#simulations">كل المواقف (${window.CommunityScenarios.items.length}) ←</a></div><div class="cards">${window.CommunityScenarios.items.slice(0,3).map(simulationCard).join('')}</div></section>`;}
function simulationLibrary(){return `<section class="page-head"><span class="label">محاكاة للتعلم اليومي</span><h1>قرار صغير قد يحميك ويحمي غيرك</h1><p>${window.CommunityScenarios.items.length} موقفًا من البيت والحي والصحة والأسرة. اختيارك يغير ما يحدث في الخطوة التالية، وسترى تفسيرًا بعد كل قرار.</p></section><div class="simulation-note"><b>تدرّب بالاختيارات فقط</b><p>لا تحتاج معدات أو تجربة فعلية. لا يوجد عد تنازلي، ويمكنك الاستماع أو تكبير النص. التدريب لا يمنح شهادة كفاءة أو أهلية طبية.</p><a href="#dashboard">سجل الجولات التي اخترت حفظها</a></div><label class="searchbox">ابحث عن موقف<input id="scenarioSearch" type="search" value="${esc(scenarioQuery)}" placeholder="السكري، الحمل، الجبس…"></label><p id="scenarioCount" role="status" aria-live="polite"></p><div id="scenarioCards" class="cards simulation-library"></div>`;}
function simulationPage(id){const s=scenarioById[id];if(!s)return '<div class="empty"><h1>هذا الموقف غير موجود</h1><a href="#simulations">استعرض المواقف</a></div>';if(!simulationRun||simulationRun.scenario.id!==id)simulationRun=new window.CommunitySimulation.Run(s);return simulationContent();}
function simulationContent(){const run=simulationRun,s=run.scenario;return `<article class="simulation-page"><a class="back" href="#simulations">→ المواقف التفاعلية</a><div class="sim-heading"><div><span class="label">تعلم دون استعجال · يمكنك الإعادة</span><h1 id="simHeading" tabindex="-1">${esc(s.title)}</h1><p>${esc(s.intro)}</p><button class="button" id="readSimulation">◖ استمع للموقف الحالي</button></div><div class="sim-art">${Art.render(s.art,s.title)}</div></div>${run.complete?simulationResult():simulationDecision()}<details class="source-details"><summary>مصادر هذا الموقف وحالة المراجعة</summary><ul>${s.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></li>`).join('')}</ul><p>نسخة السيناريو ${esc(s.version)} · إصدار التطبيق ${R.version}. مواقف للتعلم والتوعية؛ لا تمثل خدمات طبية أو تدريبًا مهنيًا معتمدًا.</p></details><p><a href="#feedback=${s.id}">أبلغنا عن غموض أو خطأ في هذا الموقف</a></p></article>`;}
function simulationDecision(){const run=simulationRun,node=run.scenario.nodes[run.current],chosen=run.pending;return `<section class="sim-stage" aria-labelledby="simQuestion"><div class="sim-progress">قرار ${run.decisions.length+(chosen?0:1)} · يتغير طول الموقف بحسب اختياراتك</div>${node.context?`<p class="sim-context">${esc(node.context)}</p>`:''}<h2 id="simQuestion">${esc(node.prompt)}</h2><div class="sim-options">${node.choices.map((c,i)=>`<button class="sim-option ${chosen?.id===c.id?'selected':''}" data-sim-choice="${esc(c.id)}" ${chosen?'disabled':''}><span class="option-number" aria-hidden="true">${i+1}</span><span>${esc(c.label)}</span></button>`).join('')}</div>${chosen?`<section class="sim-feedback ${chosen.safe?'safe':'review-choice'}" role="status"><b>${chosen.safe?'اختيار يحافظ على السلامة':'لنراجع هذا الاختيار'}</b><p>${esc(chosen.feedback)}</p><button class="button primary" id="simNext">${chosen.next===null?'راجع ما تعلمته ←':'الخطوة التالية ←'}</button></section>`:'<p class="muted">اختر ما تراه مناسبًا. لن يُحفظ اختيارك أو يُرسل تلقائيًا.</p>'}${nodeRefs(run.scenario,node)}</section>`;}
function simulationResult(){const run=simulationRun,s=run.scenario,sum=run.summary();return `<section class="sim-result"><span class="label">انتهى الموقف · يبدأ التطبيق في الحياة</span><h2>خذ معك التصرف الآمن</h2><p class="sim-score">${sum.safe} من ${sum.decisions} قراراتك كانت آمنة في هذا المسار.</p><p>${sum.critical?'ظهرت اختيارات قد تسبب خطرًا مهمًا. اقرأ تفسيرها أدناه ثم أعد الموقف للتدرب.':'راجع أسباب الاختيارات، ثم شارك الفكرة مع من يحتاجها.'} يختلف عدد القرارات بين المسارات؛ النتيجة للتعلم وليست ترتيبًا للمشاركين.</p><details class="decision-review" open><summary>راجع قراراتك بالترتيب</summary><ol>${run.decisions.map(d=>{const n=s.nodes[d.node],c=n.choices.find(x=>x.id===d.choice);return `<li><b>${esc(n.prompt)}</b><p>اخترت: ${esc(c.label)}</p><p class="${d.safe?'safe-text':'review-text'}">${esc(c.feedback)}</p></li>`;}).join('')}</ol></details><div class="choice-row"><button class="button primary" id="simRestart">أعد الموقف للتدرب</button><a class="button" href="#simulations">موقف آخر</a>${s.topics.filter(id=>byId[id]).map(id=>`<a class="button" href="#topic=${id}">${esc(byId[id].title)}</a>`).join('')}</div></section><section class="panel sim-save"><h2>تريد حفظ هذه الجولة للمتابعة؟</h2><p>هذا اختياري. تبقى الجولة على هذا الجهاز إلى أن تصدرها. يمكنك حفظ جولات لاحقة، ولا يُعد تكرار التدريب شخصًا جديدًا.</p>${run.saved?simulationSaved(run.saved):`<form id="simulationForm"><label class="field" for="simPhase">نوع الجولة</label><select id="simPhase" name="phase"><option value="practice">تدرب الآن</option><option value="later">عودة للتعلم في وقت لاحق</option></select><label class="field" for="simCampaign">رمز نشاط الطلاب — اختياري</label><input id="simCampaign" name="campaign" maxlength="24" autocomplete="off" placeholder="اتركه فارغًا للاستخدام الفردي"><label class="consent"><input type="checkbox" name="linkPrevious"><span>أنا نفس المشارك في آخر جولة محفوظة لهذا الموقف على الجهاز خلال 30 يومًا، وأريد ربط الجولتين.</span></label><label class="consent"><input type="checkbox" name="consent" required><span>أوافق على حفظ وقت الجولة واختياراتها ونسختها محليًا، دون اسم أو معلومات صحية.</span></label><button class="button primary" type="submit">احفظ هذه الجولة بإذني</button><p id="simSaveStatus" role="status"></p></form>`}</section>`;}
function renderSimulation(){if(!simulationRun)return;$('#main').innerHTML=simulationContent();$('#simHeading')?.focus({preventScroll:true});}
function simulationReadText(){const r=simulationRun;if(!r)return '';const s=r.scenario;if(r.complete)return [s.title,'انتهى الموقف',...r.decisions.flatMap(d=>{const n=s.nodes[d.node],c=n.choices.find(x=>x.id===d.choice);return[n.prompt,'اخترت',c.label,c.feedback]})].join('. ');const n=s.nodes[r.current];return[s.title,s.intro,n.context||'',n.prompt,...n.choices.map((c,i)=>'الخيار '+(i+1)+': '+c.label),...(r.pending?['اخترت',r.pending.label,r.pending.feedback]:[])].join('. ');}
function simulationSaved(row){return `<div class="measurement-result" role="status"><b>حُفظت الجولة على هذا الجهاز</b><p>لم تُرسل للكلية. يمكنك تصدير سجل المحاكاة من أدوات المتابعة.</p><a class="button" href="#dashboard">سجل المتابعة والتصدير</a><a class="button" href="#feedback=${esc(row.scenario)}">رأيك في هذا الموقف</a><p class="form-note">مرجع الجولة: ${esc(row.id)}</p></div>`;}
function saveSimulation(form){if(!simulationRun?.complete)return;const f=new FormData(form);try{simulationRecords.save(simulationRun,{consent:!!f.get('consent'),release:R.version,campaign:String(f.get('campaign')||'').trim().slice(0,24),phase:String(f.get('phase')||'practice'),linkPrevious:!!f.get('linkPrevious')});renderSimulation();}catch{notify('تعذر الحفظ. تحقق من الموافقة وإتاحة مساحة التخزين؛ يمكنك متابعة التعلم دون حفظ.');}}
function simulationDashboard(){const s=simulationRecords.summary();return `<section class="panel"><span class="label">سجل مستقل للمحاكاة</span><h2>جولات المواقف على هذا الجهاز</h2><div class="metric-grid"><div><b>${s.attempts}</b><span>جولات محفوظة بإذن</span></div><div><b>${s.decisions}</b><span>قرارات داخل هذه الجولات</span></div><div><b>${s.linked}</b><span>جولات مرتبطة بإقرار المشارك</span></div><div><b>${s.later}</b><span>جولات وصفها المشارك كعودة لاحقة</span></div></div><p>كل صف في CSV يمثل قرارًا؛ احسب الجولات من معرفاتها المميزة. لا تعني الأعداد أشخاصًا أو وصولًا مجتمعيًا، ولا تقارن النتائج بين مسارات أو نسخ مختلفة دون بيان. الربط ليس إثبات هوية أو أثر سببي.</p><div class="choice-row"><button class="button primary" id="exportSimulations">تصدير جولات المحاكاة CSV</button><button id="clearSimulations">مسح سجل المحاكاة</button><a class="button" href="#simulations">تدرب من جديد</a></div><p id="clearSimulationsPrompt" role="status"></p></section>`;}


function maternalGuide(){return `<section class="maternal-shortcuts panel" aria-label="دليل الحمل والأم والمولود"><h2>اختاري ما يهمك في هذه المرحلة</h2><p>روابط سريعة للحمل وما بعد الولادة وفحص المولود. يمكن للأسرة والمرافقين الاطلاع عليها أيضًا.</p><div class="maternal-group-grid">${R.maternalGroups.map(group=>`<section><h3>${esc(group.label)}</h3><div class="maternal-group-links">${group.items.filter(([id])=>byId[id]).map(([id,label])=>`<a class="button soft" href="#topic=${id}">${esc(label)}</a>`).join('')}</div></section>`).join('')}</div></section>`;}
function healthHubs(){return `<div class="health-hubs" aria-label="وصول مباشر إلى المجالات الصحية">${R.healthHubs.map(h=>`<button class="health-hub" data-health-hub="${h.value}" aria-pressed="${category===h.value}"><span class="hub-art" aria-hidden="true">${Art.render(h.art,h.label)}</span><span>${esc(h.label)}</span></button>`).join('')}</div>`;}
function learningSections(a){return (a.learningSections||[]).map(s=>`<section class="learning-section ${a.id==='diabetes-high-correction'?'dose-education':''}"><h2>${esc(s.title)}</h2>${s.body?`<p>${medicalText(s.body)}</p>`:''}${s.bullets?.length?listHTML(s.bullets):''}${lessonRefs(a,s)}</section>`).join('');}
function relatedTopics(a){const ids=(a.related||[]).filter(id=>byId[id]&&id!==a.id);return ids.length?`<section class="related-topics"><span class="label">أكمل ما تحتاجه</span><h2>${a.id.startsWith('diabetes')?'أدلة السكري المترابطة':'موضوعات مرتبطة'}</h2><div class="related-grid">${ids.map(id=>`<a href="#topic=${id}"><span aria-hidden="true">${Art.render(byId[id].art,byId[id].title)}</span><b>${esc(byId[id].title)}</b><span aria-hidden="true">←</span></a>`).join('')}</div></section>`:'';}


function diabetesShortcuts(a){if(a.id!=='diabetes')return '';return `<section class="diabetes-shortcuts" aria-label="ابدأ من حاجتك في السكري"><b>ابدأ مما تحتاجه الآن</b><div class="choice-row">${[['diabetes-food-portions','الطعام وكمياته'],['diabetes-high-correction','ارتفاع السكر والتصحيح'],['diabetes-sick-days','القيء والإسهال والجفاف'],['diabetes-hypoglycemia','هبوط السكر']].map(([id,label])=>`<a class="button" href="#topic=${id}">${label} ←</a>`).join('')}</div></section>`;}


function medicalText(value){return esc(value).replace(/\(250 − 150\) ÷ 50 = 2/g,match=>'<bdi dir="ltr" class="formula-inline">'+match+'</bdi>').replace(/(?:[0-9]+(?:\.[0-9]+)?\s+)?(?:mg\/dL|mmol\/L)\b/g,match=>'<bdi dir="ltr">'+match+'</bdi>');}

function surveyIcon(){return `<svg viewBox='0 0 24 24' width='23' height='23' fill='none' stroke='currentColor' stroke-width='1.8' aria-hidden='true'><path d='M4 4h16v12H9l-5 4V4Z'/><path d='M8 8h8M8 12h5'/></svg>`;}
function trialNotice(){return `<section class='trial-notice'><div><span class='label'>نطوّرها بمشاركتك</span><h2>نسخة تجريبية لاختبارها مع المجتمع</h2><p>نختبر الجوانب التقنية وسهولة الاستخدام وتصفح المواد، ونجمع آراءكم حول وضوح المعلومات وفائدتها وأفكاركم ومقترحاتكم للتحسين.</p><p>يمكنك المشاركة بعد كل تجربة أو موضوع، حتى لو سبق أن شاركت. النقد والتصحيح والتعليقات مرحّب بها.</p></div><a class='button primary' href='#feedback'>${surveyIcon()} شارك في استبيان التجربة</a></section>`;}
function surveyContext(id){const a=byId[id]||scenarioById[id]||storyById[id];return {id:a?.id||'general',item:a,simulation:!!scenarioById[id],title:a?.title||'تمريض من أجل المجتمع'};}
function currentSurveyId(){const params=new URLSearchParams(location.hash.slice(1));return params.get('story')||params.get('topic')||params.get('sim')||params.get('measure')||params.get('feedback')||'general';}
let surveyReturnFocus=null;
function openSurvey(id){if($('#main').querySelector?.('#communitySurveyFrame')){$('#communitySurveyTitle').focus();return;}const dialog=$('#communitySurveyDialog');if(!dialog||!dialog.showModal){location.hash=id&&id!=='general'?'feedback='+encodeURIComponent(id):'feedback';return;}stopReading();surveyReturnFocus=document.activeElement;$('#communitySurveyContent').innerHTML=feedback(id,true);dialog.showModal();dialog.scrollTop=0;$('#communitySurveyTitle').focus();}
function closeSurvey(){const dialog=$('#communitySurveyDialog');if(dialog?.open)dialog.close();}
function surveyFormURL(id,embedded=false){const config=window.COMMUNITY_SURVEY_FORM;if(!config?.url)return '';let url;try{url=new URL(config.url);}catch{return '';}if(url.protocol!=='https:'||url.hostname!=='docs.google.com'||!/^\/forms\/d\/(?:e\/)?[^/]+\/viewform$/.test(url.pathname))return '';const context=surveyContext(id);url.searchParams.set('usp','pp_url');if(/^entry\.\d+$/.test(config.contextEntry||''))url.searchParams.set(config.contextEntry,context.title);if(embedded)url.searchParams.set('embedded','true');else url.searchParams.delete('embedded');return url.href;}
function feedback(id,inDialog=false){const c=surveyContext(id),url=surveyFormURL(c.id,true),standalone=surveyFormURL(c.id),title=c.item?'رأيك في: '+c.title:'رأيك في تمريض من أجل المجتمع';return `<section class='community-survey' data-survey-context='${esc(c.id)}'><div class='page-head'><span class='label'>استبيان التوعية الصحية · يمكنك المشاركة أكثر من مرة</span><h${inDialog?'2':'1'} id='communitySurveyTitle' tabindex='-1'>${esc(title)}</h${inDialog?'2':'1'}><p>استبيان خاص بتطبيق تمريض من أجل المجتمع. تصل إجاباتك إلى فريق المبادرة عند الضغط على «إرسال» داخل الاستبيان. لا تكتب اسم مريض أو معلومات صحية شخصية.</p></div>${url?`<div class='survey-frame-tools'><button type='button' id='newFeedback' class='button'>بدء مشاركة جديدة</button><a class='survey-open-link' href='${esc(standalone)}' target='_blank' rel='noopener noreferrer'>إذا لم يظهر الاستبيان، افتحه هنا ↗</a></div><p class='survey-online-note'>يحتاج الاستبيان إلى اتصال بالإنترنت. بعد الإرسال يمكنك اختيار «إرسال رد آخر» داخله أو بدء مشاركة جديدة من الزر أعلاه.</p><iframe id='communitySurveyFrame' class='community-survey-frame' src='${esc(url)}' title='${esc(title)} — استبيان خاص بالتوعية الصحية' loading='eager' referrerpolicy='strict-origin-when-cross-origin'></iframe>`:`<p class='survey-online-note' role='status'>يجري تجهيز استبيان المبادرة. أعد فتح الصفحة بعد التحديث.</p>`}</section>`;}
$('#communitySurveyDialog')?.addEventListener('close',()=>{$('#communitySurveyContent').innerHTML='';surveyReturnFocus?.focus?.();});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#feedback"]');if(link){e.preventDefault();const id=new URLSearchParams(link.getAttribute('href').slice(1)).get('feedback')||currentSurveyId();openSurvey(id);return;}const b=e.target.closest('button');if(b?.id==='closeCommunitySurvey')closeSurvey();if(b?.id==='newFeedback'){const id=b.closest('.community-survey')?.dataset.surveyContext||'general';if($('#communitySurveyDialog')?.open){$('#communitySurveyContent').innerHTML=feedback(id,true);$('#communitySurveyDialog').scrollTop=0;}else{$('#main').innerHTML=feedback(id);}$('#communitySurveyTitle').focus();}});
function surveyDashboard(){const s=surveyStore.summary();return `<section class='panel'><span class='label'>استبيان النسخة التجريبية</span><h2>المشاركات المحلية من النسخة السابقة</h2><div class='metric-grid'><div><b>${s.records}</b><span>مشاركات محفوظة، لا أشخاص فريدون</span></div><div><b>${s.easy} / ${s.easeEvaluated}</b><span>وجدوا الاستخدام سهلًا من الذين قيّموه</span></div><div><b>${s.clear} / ${s.clarityEvaluated}</b><span>وجدوا المحتوى واضحًا من الذين قيّموه</span></div><div><b>${s.useful} / ${s.usefulnessEvaluated}</b><span>وجدوه مفيدًا لهم من الذين قيّموا فائدته</span></div></div><p>هذه مشاركات محلية سابقة، ولا تشمل إجابات الاستبيان المستقل الحالي. يمكنك تصديرها للاحتفاظ بها؛ التكرار والجهاز المشترك يؤثران في الأعداد، ولا تقيس الوصول العام أو الأثر الصحي.</p><div class='choice-row'><button id='exportSurvey' class='button primary'>تصدير استبيان التجربة CSV</button><button id='clearSurvey'>مسح سجل الاستبيان</button><a class='button' href='#feedback'>مشاركة أخرى</a></div><p id='clearSurveyPrompt' role='status'></p></section>`;}
function referenceDetails(refs,label){const unique=[...new Map(refs.filter(Boolean).map(s=>[s[2],s])).values()];if(!unique.length)return '';return `<details class='section-references'><summary>${label}</summary><ul>${unique.map(s=>`<li><a href='${esc(s[2])}' target='_blank' rel='noopener noreferrer'><b>${esc(s[0])}</b> · ${esc(s[1])} ↗</a></li>`).join('')}</ul></details>`;}
function sectionRefs(a,key){const specific=a.sectionSources?.[key];return referenceDetails((specific?.length?specific:a.sources).map(k=>SOURCES[k]),specific?.length?'مصادر هذا الجزء':'مراجع الموضوع');}
function lessonRefs(a,s){return referenceDetails((s.sources?.length?s.sources:a.sources).map(k=>SOURCES[k]),s.sources?.length?'مصادر هذا الجزء':'مراجع الموضوع');}
function articleSourceKeys(a){return [...new Set([...a.sources,...Object.values(a.sectionSources||{}).flat(),...(a.learningSections||[]).flatMap(s=>s.sources||[])])];}
function nodeRefs(s,n){const urls=n.sources||[],refs=urls.length?urls.map(u=>s.sources.find(x=>x.url===u)):s.sources;return referenceDetails(refs.filter(Boolean).map(x=>['المصدر الرسمي',x.title,x.url]),urls.length?'مصادر إرشادات هذا الموقف':'مراجع الموقف');}

window.addEventListener('hashchange',route);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;$('#install').hidden=false});if('speechSynthesis'in window){window.speechSynthesis.addEventListener?.('voiceschanged',loadVoices);loadVoices();}applyFont();route();const installed=()=>Boolean(navigator.standalone||window.matchMedia?.('(display-mode: standalone)').matches);$('#install').hidden=installed();window.addEventListener('appinstalled',()=>{$('#install').hidden=true;installEvent=null;});
if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async()=>{await navigator.serviceWorker.ready;const cache=await caches.open('nur-community-v0.12.1');$('#connection').textContent=await cache.match(new URL('./rich-content.js?v=0.5.2',location.href).href)?'القراءة دون اتصال متاحة للمواد المضمنة':'اتصل مرة أخرى لإكمال تحميل الإصدار الجديد';}).catch(()=>$('#connection').textContent='لم يكتمل الحفظ دون اتصال؛ افتح النسخة متصلًا.')}else $('#connection').textContent='التثبيت والحفظ دون اتصال يحتاجان النسخة المستضافة عبر HTTPS.';
